+// Cost provenance is reported, derived, or unavailable. `cost_status` keeps its
+// original two values so existing consumers are unaffected.
+function costState(observation) {
+  return profiles.missionControlExecutorState({ profile: local, observation, wrapper: null });
+}
+const reportedCost = costState({ trusted: true, cost: { amount: 0.42, unit: 'usd', source: 'claude-json' } });
+assert.equal(reportedCost.cost_status, 'known');
+assert.equal(reportedCost.cost_basis, 'reported');
+assert.deepEqual(reportedCost.cost, { amount: 0.42, unit: 'usd', source: 'claude-json' });
+const derivedCost = costState({ trusted: true, cost: { amount: 0.3, unit: 'usd', source: 'claude-model-usage' } });
+assert.equal(derivedCost.cost_status, 'known');
+assert.equal(derivedCost.cost_basis, 'derived');
+// A zero total is still a stated total and must not collapse into unavailable.
+const zeroCost = costState({ trusted: true, cost: { amount: 0, unit: 'usd', source: 'claude-json' } });
+assert.equal(zeroCost.cost_status, 'known');
+assert.equal(zeroCost.cost_basis, 'reported');
+// Untrusted, negative, or unlabelled amounts are unavailable, never known.
+for (const observation of [
+  { trusted: false, cost: { amount: 0.42, unit: 'usd', source: 'claude-json' } },
+  { trusted: true, cost: { amount: -1, unit: 'usd', source: 'claude-json' } },
+  { trusted: true, cost: { amount: 0.42, unit: 'usd', source: 'operator-estimate' } },
+  { trusted: true, cost: { amount: 0.42, unit: 'usd', source: 'constructor' } },
+  { trusted: true, cost: null },
+]) {
+  const state = costState(observation);
+  assert.equal(state.cost, null, JSON.stringify(observation));
+  assert.equal(state.cost_status, 'unknown', JSON.stringify(observation));
+  assert.equal(state.cost_basis, 'unavailable', JSON.stringify(observation));
+}
+assert.equal(profiles.costBasisFor('claude-json'), 'reported');
+assert.equal(profiles.costBasisFor('claude-model-usage'), 'derived');
+assert.equal(profiles.costBasisFor('toString'), null);

